let units = [
    (threshold: 1024*1024*1024, name: "GiB"),
    (threshold: 1024*1024, name: "MiB"),
    (threshold: 1024, name: "KiB"),
    (threshold: 1, name: "B")
]

func formatBytes(_ bytes: Int) -> String {
    let unit = units.first(where: { bytes >= $0.threshold })!
    let value = bytes / unit.threshold
    let significantDigit = extractMostSignificantDigit(from: value)

    return "\(significantDigit) \(unit.name)"
}

func extractMostSignificantDigit(from number: Int) -> Int {
    var highestPowerOfTen = 1
    var temporary = number

    while temporary >= 10 {
        temporary /= 10
        highestPowerOfTen *= 10
    }

    return temporary * highestPowerOfTen
}

while let line = readLine() {
    if let bytes = Int(line) {
        print(formatBytes(bytes))
    }
}
